contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public {
        require(recipient != address(0));
        require(recipient != address(this));

        bool rev1;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { rev1 = true; } else { rev1 = false; }

        bool rev2;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) { rev2 = true; } else { rev2 = false; }

        assert(rev2);
    }

    receive() external payable {}
}

